54	struct conn {
55		int fd;
56		uint32_t role;		/* PSS_ROLE_NONE until HELLO */
57		int64_t last_hb_ns;
58	};
59	
60	enum burst_state { BURST_NONE, BURST_PENDING, BURST_DONE };
61	
62	struct event {
63		int open;
64		uint64_t id;
65		int64_t start_mono_ns;
66		int64_t start_wall_ns;
67		int64_t last_activity_ns;
68		int pir_high;
69		uint32_t pir_edges;
70		uint32_t flags;
71		uint32_t n_images;
72		enum burst_state burst;
73		int64_t burst_deadline_ns;
74	};
75	
76	/* EWMA mean/variance of flux and log10(rms), learned outside events. */
77	struct mic_bg {
78		uint64_t n;
79		double flux_mu, flux_var;
80		double lrms_mu, lrms_var;
81		double z_max, db_max;	/* largest scores since the last heartbeat, for tuning */
82	};
83	
84	struct hub {
85		struct pss_store store;
86		int store_open;
87		int listen_fd, epoll_fd, sig_fd, tick_fd;
88		struct conn conns[MAX_CONNS];
89		struct event ev;
90		struct mic_bg mic;
91		int64_t start_ns, next_hb_ns;
92		uint64_t pir_edges, mic_frames, cam_bursts, cam_failures, events_closed, mic_onsets;
93		/* config */
94		int64_t quiet_ns;
95		uint32_t burst_frames, burst_interval_ms, floor_pct;
96		uint64_t quota_bytes;
97		double onset_z, onset_db;
98		uint32_t mic_warmup;
99		char sock_path[108];
100	};
101	
102	static struct hub hub;
103	
104	static void usage(void)
105	{
106		fprintf(stderr, "usage: hub [--quiet-ms=30000] [--burst-frames=20] [--burst-interval-ms=500]\n"
107				"           [--quota-mb=2048] [--floor-pct=5]\n"
108				"           [--onset-z=6] [--onset-db=10] [--warmup-frames=250]\n");
109	}
110	
111	static struct conn *conn_for_role(struct hub *h, uint32_t role)
112	{
113		for (int i = 0; i < MAX_CONNS; i++)
114			if (h->conns[i].fd >= 0 && h->conns[i].role == role)
115				return &h->conns[i];
116		return NULL;
117	}
118	
119	static int role_alive(struct hub *h, uint32_t role, int64_t now)
120	{
121		struct conn *c = conn_for_role(h, role);
122	
123		return c != NULL && now - c->last_hb_ns < HB_STALE_NS;
124	}
125	
126	static void trigger_burst(struct hub *h, int64_t now)
127	{
128		struct event *ev = &h->ev;
129		struct conn *cam = conn_for_role(h, PSS_ROLE_CAM);
130		struct pss_msg m;
131		uint32_t evicted = 0;
132		int q;
133	
134		if (cam == NULL) {
135			pss_log("event %" PRIu64 ": camd not connected, no images", ev->id);
136			ev->flags |= PSS_EVF_NO_IMAGES;
137			return;
138		}
139		q = clip_enforce_quota(h->store.clips_dir_fd, h->quota_bytes, BURST_EST_BYTES, h->floor_pct, &evicted);
140		if (q != 0) {
141			pss_log("event %" PRIu64 ": %s, no images", ev->id, q > 0 ? "clips disabled" : "quota check failed");
142			ev->flags |= PSS_EVF_NO_IMAGES;
143			return;
144		}
145		pss_msg_init(&m, PSS_MSG_CAM_TRIGGER);
146		m.u.cam_trigger.event_id = ev->id;
147		m.u.cam_trigger.frames = h->burst_frames;
148		m.u.cam_trigger.interval_ms = h->burst_interval_ms;
149		if (ipc_send(cam->fd, &m) != 0) {
150			pss_log("event %" PRIu64 ": trigger to camd failed: %s", ev->id, strerror(errno));
151			ev->flags |= PSS_EVF_NO_IMAGES;
152			return;
153		}
154		ev->burst = BURST_PENDING;
155		ev->burst_deadline_ns = now + (int64_t)h->burst_frames * h->burst_interval_ms * PSS_NS_PER_MS + BURST_SLACK_NS;
156		h->cam_bursts++;
157	}
158	
159	/* pir: 1 if a PIR rise opened the event, 0 for a sound onset. */
160	static void open_event(struct hub *h, int64_t ts, int64_t now, int pir)
161	{
162		struct event *ev = &h->ev;
163	
164		memset(ev, 0, sizeof *ev);
165		ev->open = 1;
166		ev->id = h->store.next_event_id++;
167		ev->start_mono_ns = ts;
168		ev->start_wall_ns = pss_wall_ns() - (now - ts);
169		ev->last_activity_ns = now;
170		ev->pir_high = pir;
171		ev->pir_edges = pir ? 1 : 0;
172		if (!role_alive(h, PSS_ROLE_MIC, now))
173			ev->flags |= PSS_EVF_AUDIO_OFFLINE;
174		pss_log("event %" PRIu64 " opened (%s)", ev->id, pir ? "PIR rise" : "sound onset");
175		trigger_burst(h, now);
176	}
177	
178	/* Writes the event record and makes it durable. 0, or -1 on a store failure. */
179	static int close_event(struct hub *h, int64_t end_ns, uint32_t extra_flags)
180	{
181		struct event *ev = &h->ev;
182		struct pss_rec_event r;
183	
184		memset(&r, 0, sizeof r);
185		r.event_id = ev->id;
186		r.start_mono_ns = ev->start_mono_ns;
187		r.end_mono_ns = end_ns;
188		r.start_wall_ns = ev->start_wall_ns;
189		r.kind = ev->pir_edges > 0 ? PSS_EV_MOTION_ONLY : PSS_EV_SOUND_ONLY;
190		r.flags = ev->flags | extra_flags;
191		r.pir_edges = ev->pir_edges;
192		r.n_images = ev->n_images;
193		if (store_event_close(&h->store, &r) != 0) {
194			pss_log("event %" PRIu64 ": store write failed; exiting so recovery runs", ev->id);
195			return -1;
196		}
197		pss_log("event %" PRIu64 " closed: %s dur=%.1fs edges=%" PRIu32 " images=%" PRIu32 "%s%s",
198			ev->id, r.kind == PSS_EV_MOTION_ONLY ? "MOTION_ONLY" : "SOUND_ONLY", (double)(end_ns - ev->start_mono_ns) / PSS_NS_PER_S, r.pir_edges, r.n_images,
199			(r.flags & PSS_EVF_NO_IMAGES) ? " no-images" : "",
200			(r.flags & PSS_EVF_AUDIO_OFFLINE) ? " audio-offline" : "");
201		h->events_closed++;
202		ev->open = 0;
203		return 0;
204	}
205	
206	static void on_cam_done(struct hub *h, const struct pss_msg *m)
207	{
208		struct event *ev = &h->ev;
209		uint64_t id = m->u.cam_done.event_id;
210		uint32_t n = 0;
211	
212		if (!ev->open || id != ev->id || ev->burst != BURST_PENDING) {
213			pss_log("camd: late result for event %" PRIu64 ", discarding", id);
214			clip_discard(h->store.clips_dir_fd, id);
215			return;
216		}
217		ev->burst = BURST_DONE;
218		if (m->u.cam_done.status != 0 || m->u.cam_done.frames == 0) {
219			h->cam_failures++;
220			ev->flags |= PSS_EVF_NO_IMAGES;
221			pss_log("event %" PRIu64 ": burst failed (status %" PRId32 ", %" PRIu32 " frames)",
222				id, m->u.cam_done.status, m->u.cam_done.frames);
223			clip_discard(h->store.clips_dir_fd, id);
224			return;
225		}
226		if (clip_commit(h->store.clips_dir_fd, id, &n) != 0) {
227			h->cam_failures++;
228			ev->flags |= PSS_EVF_NO_IMAGES;
229			clip_discard(h->store.clips_dir_fd, id);
230			return;
231		}
232		ev->n_images = n;
233		pss_log("event %" PRIu64 ": committed %" PRIu32 " images to clips/%" PRIu64 ".dir", id, n, id);
234	}
235	
236	static void on_pir_edge(struct hub *h, const struct pss_msg *m, int64_t now)
237	{
238		struct event *ev = &h->ev;
239	
240		h->pir_edges++;
241		if (m->u.pir.rising) {
242			if (!ev->open) {
243				open_event(h, m->mono_ns, now, 1);
244				return;
245			}
246			ev->pir_edges++;
247			ev->pir_high = 1;
248			ev->last_activity_ns = now;
249		} else if (ev->open) {
250			ev->pir_high = 0;
251			ev->last_activity_ns = now;
252		}
253	}
254	
255	static void mic_bg_update(struct mic_bg *b, double flux, double lrms)
256	{
257		double a, d;
258	
259		b->n++;
260		a = 1.0 / (double)b->n;
261		if (a < MIC_ALPHA_MIN)
262			a = MIC_ALPHA_MIN;
263		d = flux - b->flux_mu;
264		b->flux_mu += a * d;
265		b->flux_var = (1.0 - a) * (b->flux_var + a * d * d);
266		d = lrms - b->lrms_mu;
267		b->lrms_mu += a * d;
268		b->lrms_var = (1.0 - a) * (b->lrms_var + a * d * d);
269	}
270	
271	static void on_mic_frame(struct hub *h, const struct pss_msg *m, int64_t now)
272	{
273		struct mic_bg *b = &h->mic;
274		struct event *ev = &h->ev;
275		double flux = m->u.mic.flux;
276		double rms = m->u.mic.rms;
277		double lrms, z, db;
278		int onset;
279	
280		h->mic_frames++;
281		if (!isfinite(flux) || !isfinite(rms) || rms < 0) {
282			pss_log("micd: non-finite frame ignored");
283			return;
284		}
285		lrms = log10(rms > MIC_RMS_FLOOR ? rms : MIC_RMS_FLOOR);
286		z = (flux - b->flux_mu) / sqrt(b->flux_var > MIC_FLUX_VAR_FLOOR ? b->flux_var : MIC_FLUX_VAR_FLOOR);
287		db = 20.0 * (lrms - b->lrms_mu);
288		onset = b->n >= h->mic_warmup && z >= h->onset_z && db >= h->onset_db;
289		if (b->n >= h->mic_warmup && !ev->open) {
290			if (z > b->z_max)
291				b->z_max = z;
292			if (db > b->db_max)
293				b->db_max = db;
294		}
295		if (onset) {
296			h->mic_onsets++;
297			pss_log("sound onset: flux z=%.1f, +%.1f dB over background", z, db);
298			if (!ev->open)
299				open_event(h, m->mono_ns, now, 0);
300			else
301				ev->last_activity_ns = now;
302			return;
303		}
304		if (!ev->open)
305			mic_bg_update(b, flux, lrms);
306	}
307	
308	static void conn_drop(struct hub *h, int idx, const char *why)
309	{
310		struct conn *c = &h->conns[idx];
311	
312		if (epoll_ctl(h->epoll_fd, EPOLL_CTL_DEL, c->fd, NULL) != 0)
313			pss_log("epoll_ctl DEL: %s", strerror(errno));
314		if (close(c->fd) != 0)
315			pss_log("close conn: %s", strerror(errno));
316		pss_log("%s disconnected (%s)", pss_role_name(c->role), why);
317		if (c->role == PSS_ROLE_CAM && h->ev.open && h->ev.burst == BURST_PENDING) {
318			h->ev.burst = BURST_DONE;
319			h->ev.flags |= PSS_EVF_NO_IMAGES;
320			h->cam_failures++;
321		}
322		if (c->role == PSS_ROLE_PIR)
323			h->ev.pir_high = 0; /* don't hold an event open on a dead sensor */
324		if (c->role == PSS_ROLE_MIC)
325			memset(&h->mic, 0, sizeof h->mic); /* relearn: the device or room may differ */
326		c->fd = -1;
327		c->role = PSS_ROLE_NONE;
328	}
329	
330	static void handle_msg(struct hub *h, int idx, const struct pss_msg *m, int64_t now)
331	{
332		struct conn *c = &h->conns[idx];
333	
334		if (c->role == PSS_ROLE_NONE && m->type != PSS_MSG_HELLO) {
335			conn_drop(h, idx, "message before HELLO");
336			return;
337		}
338		switch (m->type) {
339		case PSS_MSG_HELLO:
340			if (m->u.hello.role < PSS_ROLE_PIR || m->u.hello.role > PSS_ROLE_MIC) {
341				conn_drop(h, idx, "bad role");
342				return;
343			}
344			c->role = m->u.hello.role;
345			c->last_hb_ns = now;
346			pss_log("%s connected (pid %" PRIu32 ")", pss_role_name(c->role), m->u.hello.pid);
347			break;
348		case PSS_MSG_HEARTBEAT:
349			c->last_hb_ns = now;
350			break;
351		case PSS_MSG_PIR_EDGE:
352			on_pir_edge(h, m, now);
353			break;
354		case PSS_MSG_CAM_DONE:
355			on_cam_done(h, m);
356			break;
357		case PSS_MSG_MIC_FRAME:
358			on_mic_frame(h, m, now);
359			break;
360		default:
361			pss_log("%s: unknown message type %u", pss_role_name(c->role), m->type);
362			break;
363		}
364	}
365	
366	static void conn_readable(struct hub *h, int idx, int64_t now)
367	{
368		struct pss_msg m;
369		int r;
370	
371		while (h->conns[idx].fd >= 0) {
372			r = ipc_recv(h->conns[idx].fd, &m);
373			if (r == 1) {
374				handle_msg(h, idx, &m, now);
375				continue;
376			}
377			if (r == 0)
378				conn_drop(h, idx, "EOF");
379			else if (errno != EAGAIN)
380				conn_drop(h, idx, strerror(errno));
381			return;
382		}
383	}
384	
385	static void accept_all(struct hub *h, int64_t now)
386	{
387		for (;;) {
388			struct epoll_event ee = { .events = EPOLLIN };
389			int fd = accept4(h->listen_fd, NULL, NULL, SOCK_CLOEXEC | SOCK_NONBLOCK);
390			int idx = -1;
391	
392			if (fd < 0) {
393				if (errno != EAGAIN && errno != EINTR)
394					pss_log("accept4: %s", strerror(errno));
395				return;
396			}
397			for (int i = 0; i < MAX_CONNS; i++) {
398				if (h->conns[i].fd < 0) {
399					idx = i;
400					break;
401				}
402			}
403			if (idx < 0) {
404				pss_log("too many connections, refusing one");
405				close(fd);
406				continue;
407			}
408			ee.data.u32 = (uint32_t)idx;
409			if (epoll_ctl(h->epoll_fd, EPOLL_CTL_ADD, fd, &ee) != 0) {
410				pss_log("epoll_ctl ADD: %s", strerror(errno));
411				close(fd);
412				continue;
413			}
414			h->conns[idx] = (struct conn){ .fd = fd, .role = PSS_ROLE_NONE, .last_hb_ns = now };
415		}
416	}
417	
418	static const char *alive_str(struct hub *h, uint32_t role, int64_t now)
419	{
420		if (role_alive(h, role, now))
421			return "ok";
422		return conn_for_role(h, role) ? "STALE" : "absent";
423	}
424	
425	/* Stats record (1/min) doubles as the soak heartbeat line. 0 or -1. */
426	static int write_stats(struct hub *h, int64_t now)
427	{
428		struct pss_rec_stats r;
429	
430		memset(&r, 0, sizeof r);
431		r.mono_ns = now;
432		r.wall_ns = pss_wall_ns();
433		r.pir_edges = h->pir_edges;
434		r.mic_frames = h->mic_frames;
435		r.cam_bursts = h->cam_bursts;
436		r.cam_failures = h->cam_failures;
437		for (uint32_t role = PSS_ROLE_PIR; role <= PSS_ROLE_MIC; role++)
438			if (role_alive(h, role, now))
439				r.sensors_ok |= 1u << role;
440		if (store_append(&h->store, PSS_LOG_STATS, PSS_REC_STATS, &r, sizeof r) != 0 ||
441		    store_sync(&h->store, PSS_LOG_STATS) != 0)
442			return -1;
443		pss_log("hb: up=%" PRId64 "s pird=%s camd=%s micd=%s edges=%" PRIu64 " events=%" PRIu64
444			" bursts=%" PRIu64 " cam_fail=%" PRIu64 " mic_frames=%" PRIu64 " mic_onsets=%" PRIu64
445			" mic_zmax=%.1f mic_dbmax=%.1f",
446			(now - h->start_ns) / PSS_NS_PER_S, alive_str(h, PSS_ROLE_PIR, now),
447			alive_str(h, PSS_ROLE_CAM, now), alive_str(h, PSS_ROLE_MIC, now),
448			h->pir_edges, h->events_closed, h->cam_bursts, h->cam_failures, h->mic_frames, h->mic_onsets,
449			h->mic.z_max, h->mic.db_max);
450		h->mic.z_max = h->mic.db_max = 0;
451		return 0;
452	}
453	
454	static int tick(struct hub *h, int64_t now)
455	{
456		struct event *ev = &h->ev;
457	
458		if (ev->open && ev->burst == BURST_PENDING && now > ev->burst_deadline_ns) {
459			pss_log("event %" PRIu64 ": camd result overdue, no images", ev->id);
460			ev->burst = BURST_DONE;
461			ev->flags |= PSS_EVF_NO_IMAGES;
462			h->cam_failures++;
463		}
464		if (ev->open && !ev->pir_high && ev->burst != BURST_PENDING &&
465		    now - ev->last_activity_ns >= h->quiet_ns && close_event(h, ev->last_activity_ns, 0) != 0)
466			return -1;
467		if (now >= h->next_hb_ns) {
468			if (write_stats(h, now) != 0)
469				return -1;
470			h->next_hb_ns = now + HB_EVERY_NS;
471		}
472		return 0;
473	}

file.content:
struct conn {
	int fd;
	uint32_t role;		/* PSS_ROLE_NONE until HELLO */
	int64_t last_hb_ns;
};

enum burst_state { BURST_NONE, BURST_PENDING, BURST_DONE };

struct event {
	int open;
	uint64_t id;
	int64_t start_mono_ns;
	int64_t start_wall_ns;
	int64_t last_activity_ns;
	int pir_high;
	uint32_t pir_edges;
	uint32_t flags;
	uint32_t n_images;
	enum burst_state burst;
	int64_t burst_deadline_ns;
};

/* EWMA mean/variance of flux and log10(rms), learned outside events. */
struct mic_bg {
	uint64_t n;
	double flux_mu, flux_var;
	double lrms_mu, lrms_var;
	double z_max, db_max;	/* largest scores since the last heartbeat, for tuning */
};

struct hub {
	struct pss_store store;
	int store_open;
	int listen_fd, epoll_fd, sig_fd, tick_fd;
	struct conn conns[MAX_CONNS];
	struct event ev;
	struct mic_bg mic;
	int64_t start_ns, next_hb_ns;
	uint64_t pir_edges, mic_frames, cam_bursts, cam_failures, events_closed, mic_onsets;
	/* config */
	int64_t quiet_ns;
	uint32_t burst_frames, burst_interval_ms, floor_pct;
	uint64_t quota_bytes;
	double onset_z, onset_db;
	uint32_t mic_warmup;
	char sock_path[108];
};

static struct hub hub;

static void usage(void)
{
	fprintf(stderr, "usage: hub [--quiet-ms=30000] [--burst-frames=20] [--burst-interval-ms=500]\n"
			"           [--quota-mb=2048] [--floor-pct=5]\n"
			"           [--onset-z=6] [--onset-db=10] [--warmup-frames=250]\n");
}

static struct conn *conn_for_role(struct hub *h, uint32_t role)
{
	for (int i = 0; i < MAX_CONNS; i++)
		if (h->conns[i].fd >= 0 && h->conns[i].role == role)
			return &h->conns[i];
	return NULL;
}

static int role_alive(struct hub *h, uint32_t role, int64_t now)
{
	struct conn *c = conn_for_role(h, role);

	return c != NULL && now - c->last_hb_ns < HB_STALE_NS;
}

static void trigger_burst(struct hub *h, int64_t now)
{
	struct event *ev = &h->ev;
	struct conn *cam = conn_for_role(h, PSS_ROLE_CAM);
	struct pss_msg m;
	uint32_t evicted = 0;
	int q;

	if (cam == NULL) {
		pss_log("event %" PRIu64 ": camd not connected, no images", ev->id);
		ev->flags |= PSS_EVF_NO_IMAGES;
		return;
	}
	q = clip_enforce_quota(h->store.clips_dir_fd, h->quota_bytes, BURST_EST_BYTES, h->floor_pct, &evicted);
	if (q != 0) {
		pss_log("event %" PRIu64 ": %s, no images", ev->id, q > 0 ? "clips disabled" : "quota check failed");
		ev->flags |= PSS_EVF_NO_IMAGES;
		return;
	}
	pss_msg_init(&m, PSS_MSG_CAM_TRIGGER);
	m.u.cam_trigger.event_id = ev->id;
	m.u.cam_trigger.frames = h->burst_frames;
	m.u.cam_trigger.interval_ms = h->burst_interval_ms;
	if (ipc_send(cam->fd, &m) != 0) {
		pss_log("event %" PRIu64 ": trigger to camd failed: %s", ev->id, strerror(errno));
		ev->flags |= PSS_EVF_NO_IMAGES;
		return;
	}
	ev->burst = BURST_PENDING;
	ev->burst_deadline_ns = now + (int64_t)h->burst_frames * h->burst_interval_ms * PSS_NS_PER_MS + BURST_SLACK_NS;
	h->cam_bursts++;
}

/* pir: 1 if a PIR rise opened the event, 0 for a sound onset. */
static void open_event(struct hub *h, int64_t ts, int64_t now, int pir)
{
	struct event *ev = &h->ev;

	memset(ev, 0, sizeof *ev);
	ev->open = 1;
	ev->id = h->store.next_event_id++;
	ev->start_mono_ns = ts;
	ev->start_wall_ns = pss_wall_ns() - (now - ts);
	ev->last_activity_ns = now;
	ev->pir_high = pir;
	ev->pir_edges = pir ? 1 : 0;
	if (!role_alive(h, PSS_ROLE_MIC, now))
		ev->flags |= PSS_EVF_AUDIO_OFFLINE;
	pss_log("event %" PRIu64 " opened (%s)", ev->id, pir ? "PIR rise" : "sound onset");
	trigger_burst(h, now);
}

/* Writes the event record and makes it durable. 0, or -1 on a store failure. */
static int close_event(struct hub *h, int64_t end_ns, uint32_t extra_flags)
{
	struct event *ev = &h->ev;
	struct pss_rec_event r;

	memset(&r, 0, sizeof r);
	r.event_id = ev->id;
	r.start_mono_ns = ev->start_mono_ns;
	r.end_mono_ns = end_ns;
	r.start_wall_ns = ev->start_wall_ns;
	r.kind = ev->pir_edges > 0 ? PSS_EV_MOTION_ONLY : PSS_EV_SOUND_ONLY;
	r.flags = ev->flags | extra_flags;
	r.pir_edges = ev->pir_edges;
	r.n_images = ev->n_images;
	if (store_event_close(&h->store, &r) != 0) {
		pss_log("event %" PRIu64 ": store write failed; exiting so recovery runs", ev->id);
		return -1;
	}
	pss_log("event %" PRIu64 " closed: %s dur=%.1fs edges=%" PRIu32 " images=%" PRIu32 "%s%s",
		ev->id, r.kind == PSS_EV_MOTION_ONLY ? "MOTION_ONLY" : "SOUND_ONLY", (double)(end_ns - ev->start_mono_ns) / PSS_NS_PER_S, r.pir_edges, r.n_images,
		(r.flags & PSS_EVF_NO_IMAGES) ? " no-images" : "",
		(r.flags & PSS_EVF_AUDIO_OFFLINE) ? " audio-offline" : "");
	h->events_closed++;
	ev->open = 0;
	return 0;
}

static void on_cam_done(struct hub *h, const struct pss_msg *m)
{
	struct event *ev = &h->ev;
	uint64_t id = m->u.cam_done.event_id;
	uint32_t n = 0;

	if (!ev->open || id != ev->id || ev->burst != BURST_PENDING) {
		pss_log("camd: late result for event %" PRIu64 ", discarding", id);
		clip_discard(h->store.clips_dir_fd, id);
		return;
	}
	ev->burst = BURST_DONE;
	if (m->u.cam_done.status != 0 || m->u.cam_done.frames == 0) {
		h->cam_failures++;
		ev->flags |= PSS_EVF_NO_IMAGES;
		pss_log("event %" PRIu64 ": burst failed (status %" PRId32 ", %" PRIu32 " frames)",
			id, m->u.cam_done.status, m->u.cam_done.frames);
		clip_discard(h->store.clips_dir_fd, id);
		return;
	}
	if (clip_commit(h->store.clips_dir_fd, id, &n) != 0) {
		h->cam_failures++;
		ev->flags |= PSS_EVF_NO_IMAGES;
		clip_discard(h->store.clips_dir_fd, id);
		return;
	}
	ev->n_images = n;
	pss_log("event %" PRIu64 ": committed %" PRIu32 " images to clips/%" PRIu64 ".dir", id, n, id);
}

static void on_pir_edge(struct hub *h, const struct pss_msg *m, int64_t now)
{
	struct event *ev = &h->ev;

	h->pir_edges++;
	if (m->u.pir.rising) {
		if (!ev->open) {
			open_event(h, m->mono_ns, now, 1);
			return;
		}
		ev->pir_edges++;
		ev->pir_high = 1;
		ev->last_activity_ns = now;
	} else if (ev->open) {
		ev->pir_high = 0;
		ev->last_activity_ns = now;
	}
}

static void mic_bg_update(struct mic_bg *b, double flux, double lrms)
{
	double a, d;

	b->n++;
	a = 1.0 / (double)b->n;
	if (a < MIC_ALPHA_MIN)
		a = MIC_ALPHA_MIN;
	d = flux - b->flux_mu;
	b->flux_mu += a * d;
	b->flux_var = (1.0 - a) * (b->flux_var + a * d * d);
	d = lrms - b->lrms_mu;
	b->lrms_mu += a * d;
	b->lrms_var = (1.0 - a) * (b->lrms_var + a * d * d);
}

static void on_mic_frame(struct hub *h, const struct pss_msg *m, int64_t now)
{
	struct mic_bg *b = &h->mic;
	struct event *ev = &h->ev;
	double flux = m->u.mic.flux;
	double rms = m->u.mic.rms;
	double lrms, z, db;
	int onset;

	h->mic_frames++;
	if (!isfinite(flux) || !isfinite(rms) || rms < 0) {
		pss_log("micd: non-finite frame ignored");
		return;
	}
	lrms = log10(rms > MIC_RMS_FLOOR ? rms : MIC_RMS_FLOOR);
	z = (flux - b->flux_mu) / sqrt(b->flux_var > MIC_FLUX_VAR_FLOOR ? b->flux_var : MIC_FLUX_VAR_FLOOR);
	db = 20.0 * (lrms - b->lrms_mu);
	onset = b->n >= h->mic_warmup && z >= h->onset_z && db >= h->onset_db;
	if (b->n >= h->mic_warmup && !ev->open) {
		if (z > b->z_max)
			b->z_max = z;
		if (db > b->db_max)
			b->db_max = db;
	}
	if (onset) {
		h->mic_onsets++;
		pss_log("sound onset: flux z=%.1f, +%.1f dB over background", z, db);
		if (!ev->open)
			open_event(h, m->mono_ns, now, 0);
		else
			ev->last_activity_ns = now;
		return;
	}
	if (!ev->open)
		mic_bg_update(b, flux, lrms);
}

static void conn_drop(struct hub *h, int idx, const char *why)
{
	struct conn *c = &h->conns[idx];

	if (epoll_ctl(h->epoll_fd, EPOLL_CTL_DEL, c->fd, NULL) != 0)
		pss_log("epoll_ctl DEL: %s", strerror(errno));
	if (close(c->fd) != 0)
		pss_log("close conn: %s", strerror(errno));
	pss_log("%s disconnected (%s)", pss_role_name(c->role), why);
	if (c->role == PSS_ROLE_CAM && h->ev.open && h->ev.burst == BURST_PENDING) {
		h->ev.burst = BURST_DONE;
		h->ev.flags |= PSS_EVF_NO_IMAGES;
		h->cam_failures++;
	}
	if (c->role == PSS_ROLE_PIR)
		h->ev.pir_high = 0; /* don't hold an event open on a dead sensor */
	if (c->role == PSS_ROLE_MIC)
		memset(&h->mic, 0, sizeof h->mic); /* relearn: the device or room may differ */
	c->fd = -1;
	c->role = PSS_ROLE_NONE;
}

static void handle_msg(struct hub *h, int idx, const struct pss_msg *m, int64_t now)
{
	struct conn *c = &h->conns[idx];

	if (c->role == PSS_ROLE_NONE && m->type != PSS_MSG_HELLO) {
		conn_drop(h, idx, "message before HELLO");
		return;
	}
	switch (m->type) {
	case PSS_MSG_HELLO:
		if (m->u.hello.role < PSS_ROLE_PIR || m->u.hello.role > PSS_ROLE_MIC) {
			conn_drop(h, idx, "bad role");
			return;
		}
		c->role = m->u.hello.role;
		c->last_hb_ns = now;
		pss_log("%s connected (pid %" PRIu32 ")", pss_role_name(c->role), m->u.hello.pid);
		break;
	case PSS_MSG_HEARTBEAT:
		c->last_hb_ns = now;
		break;
	case PSS_MSG_PIR_EDGE:
		on_pir_edge(h, m, now);
		break;
	case PSS_MSG_CAM_DONE:
		on_cam_done(h, m);
		break;
	case PSS_MSG_MIC_FRAME:
		on_mic_frame(h, m, now);
		break;
	default:
		pss_log("%s: unknown message type %u", pss_role_name(c->role), m->type);
		break;
	}
}

static void conn_readable(struct hub *h, int idx, int64_t now)
{
	struct pss_msg m;
	int r;

	while (h->conns[idx].fd >= 0) {
		r = ipc_recv(h->conns[idx].fd, &m);
		if (r == 1) {
			handle_msg(h, idx, &m, now);
			continue;
		}
		if (r == 0)
			conn_drop(h, idx, "EOF");
		else if (errno != EAGAIN)
			conn_drop(h, idx, strerror(errno));
		return;
	}
}

static void accept_all(struct hub *h, int64_t now)
{
	for (;;) {
		struct epoll_event ee = { .events = EPOLLIN };
		int fd = accept4(h->listen_fd, NULL, NULL, SOCK_CLOEXEC | SOCK_NONBLOCK);
		int idx = -1;

		if (fd < 0) {
			if (errno != EAGAIN && errno != EINTR)
				pss_log("accept4: %s", strerror(errno));
			return;
		}
		for (int i = 0; i < MAX_CONNS; i++) {
			if (h->conns[i].fd < 0) {
				idx = i;
				break;
			}
		}
		if (idx < 0) {
			pss_log("too many connections, refusing one");
			close(fd);
			continue;
		}
		ee.data.u32 = (uint32_t)idx;
		if (epoll_ctl(h->epoll_fd, EPOLL_CTL_ADD, fd, &ee) != 0) {
			pss_log("epoll_ctl ADD: %s", strerror(errno));
			close(fd);
			continue;
		}
		h->conns[idx] = (struct conn){ .fd = fd, .role = PSS_ROLE_NONE, .last_hb_ns = now };
	}
}

static const char *alive_str(struct hub *h, uint32_t role, int64_t now)
{
	if (role_alive(h, role, now))
		return "ok";
	return conn_for_role(h, role) ? "STALE" : "absent";
}

/* Stats record (1/min) doubles as the soak heartbeat line. 0 or -1. */
static int write_stats(struct hub *h, int64_t now)
{
	struct pss_rec_stats r;

	memset(&r, 0, sizeof r);
	r.mono_ns = now;
	r.wall_ns = pss_wall_ns();
	r.pir_edges = h->pir_edges;
	r.mic_frames = h->mic_frames;
	r.cam_bursts = h->cam_bursts;
	r.cam_failures = h->cam_failures;
	for (uint32_t role = PSS_ROLE_PIR; role <= PSS_ROLE_MIC; role++)
		if (role_alive(h, role, now))
			r.sensors_ok |= 1u << role;
	if (store_append(&h->store, PSS_LOG_STATS, PSS_REC_STATS, &r, sizeof r) != 0 ||
	    store_sync(&h->store, PSS_LOG_STATS) != 0)
		return -1;
	pss_log("hb: up=%" PRId64 "s pird=%s camd=%s micd=%s edges=%" PRIu64 " events=%" PRIu64
		" bursts=%" PRIu64 " cam_fail=%" PRIu64 " mic_frames=%" PRIu64 " mic_onsets=%" PRIu64
		" mic_zmax=%.1f mic_dbmax=%.1f",
		(now - h->start_ns) / PSS_NS_PER_S, alive_str(h, PSS_ROLE_PIR, now),
		alive_str(h, PSS_ROLE_CAM, now), alive_str(h, PSS_ROLE_MIC, now),
		h->pir_edges, h->events_closed, h->cam_bursts, h->cam_failures, h->mic_frames, h->mic_onsets,
		h->mic.z_max, h->mic.db_max);
	h->mic.z_max = h->mic.db_max = 0;
	return 0;
}

static int tick(struct hub *h, int64_t now)
{
	struct event *ev = &h->ev;

	if (ev->open && ev->burst == BURST_PENDING && now > ev->burst_deadline_ns) {
		pss_log("event %" PRIu64 ": camd result overdue, no images", ev->id);
		ev->burst = BURST_DONE;
		ev->flags |= PSS_EVF_NO_IMAGES;
		h->cam_failures++;
	}
	if (ev->open && !ev->pir_high && ev->burst != BURST_PENDING &&
	    now - ev->last_activity_ns >= h->quiet_ns && close_event(h, ev->last_activity_ns, 0) != 0)
		return -1;
	if (now >= h->next_hb_ns) {
		if (write_stats(h, now) != 0)
			return -1;
		h->next_hb_ns = now + HB_EVERY_NS;
	}
	return 0;
}

content.content:
enum pss_rec_type {
	PSS_REC_BOOT = 1,	/* events log */
	PSS_REC_EVENT = 2,	/* events log: a complete event, or the close of an EVENT_OPEN */
	PSS_REC_STATS = 3,	/* stats log only */
	PSS_REC_EVENT_OPEN = 4,	/* events log: ENTRY confirmed, made durable at once */
};

enum pss_event_kind {
	PSS_EV_MOTION_ONLY = 1,
	PSS_EV_ENTRY = 2,	/* needs fusion (M4) */
	PSS_EV_SOUND_ONLY = 3,	/* needs fusion (M4) */
};

enum pss_event_flag {
	PSS_EVF_NO_IMAGES = 1u << 0,
	PSS_EVF_AUDIO_OFFLINE = 1u << 1,
	PSS_EVF_CLOSED_AT_SHUTDOWN = 1u << 2,
	PSS_EVF_INTERRUPTED = 1u << 3,	/* opened, power lost before close; end unknown */
};

/* Payload structs have no implicit padding; read them back with memcpy (payloads are unaligned). */
struct pss_rec_boot {
	uint64_t boot_no;
	int64_t mono_ns;
	int64_t wall_ns;
};

/* Images, if any, live in clips/<event_id>.dir. */
struct pss_rec_event {
	uint64_t event_id;
	int64_t start_mono_ns;
	int64_t end_mono_ns;
	int64_t start_wall_ns;
	uint32_t kind;
	uint32_t flags;
	uint32_t pir_edges;
	uint32_t n_images;
};

struct pss_rec_event_open {
	uint64_t event_id;
	int64_t start_mono_ns;
	int64_t start_wall_ns;
	uint32_t kind;
	uint32_t flags;
};

struct pss_rec_stats {
	int64_t mono_ns;
	int64_t wall_ns;
	uint64_t pir_edges;
/* Appends one record (not yet durable) to the given log. STATS records go to
 * the stats log and every other type to the events log. 0 or -1. */
int store_append(struct pss_store *s, enum pss_log_which which, uint16_t type, const void *payload, uint32_t len);
/* fdatasync the given log's current segment. 0 or -1. */
