	hp = spawn((char *[]){ hub, "--quiet-ms=300", "--burst-frames=3", "--burst-interval-ms=20",
			       "--warmup-frames=250", "--onset-z=6", "--onset-db=10", NULL });
	CHECK(hp > 0);
	CHECK(ipc_sock_path(sock, sizeof sock) == 0);
