	/* 10 s of a steady fan, then the fan slowly turned up ~9.5 dB over 30 s. */
	for (i = 0; i < 500; i++)
		send_fan(fd, &st, 0.02);
	for (i = 0; i < 1500; i++)
		send_fan(fd, &st, 0.02 * (1.0 + 2.0 * i / 1500.0));
