/* pird's edge filter: warm-up suppression and duplicate-direction suppression. */
#include "t.h"

#include "capture/pir/pir_logic.h"

#define S 1000000000LL

static void test_warmup_suppresses_then_forwards(void)
{
	struct pir_filter f;

	pir_filter_init(&f, 100 * S, 60 * S, 0);
	CHECK(pir_filter_edge(&f, 1, 110 * S) == PIR_WARMUP);
	CHECK(pir_filter_edge(&f, 0, 120 * S) == PIR_WARMUP);
	CHECK(pir_filter_edge(&f, 1, 160 * S) == PIR_FORWARD); /* boundary: warm-up over */
	CHECK(pir_filter_edge(&f, 0, 163 * S) == PIR_FORWARD);
	CHECK(f.forwarded == 2 && f.suppressed == 2);
}

static void test_level_tracked_through_warmup(void)
{
	struct pir_filter f;

	/* Rose during warm-up and is still high: the next edge must be a fall. */
	pir_filter_init(&f, 0, 60 * S, 0);
	CHECK(pir_filter_edge(&f, 1, 59 * S) == PIR_WARMUP);
	CHECK(pir_filter_edge(&f, 1, 61 * S) == PIR_DUPLICATE);
	CHECK(pir_filter_edge(&f, 0, 62 * S) == PIR_FORWARD);
}

static void test_duplicates_dropped(void)
{
	struct pir_filter f;

	pir_filter_init(&f, 0, 0, 1);
	CHECK(pir_filter_edge(&f, 1, 1 * S) == PIR_DUPLICATE);
	CHECK(pir_filter_edge(&f, 0, 2 * S) == PIR_FORWARD);
	CHECK(pir_filter_edge(&f, 0, 3 * S) == PIR_DUPLICATE);
	CHECK(pir_filter_edge(&f, 1, 4 * S) == PIR_FORWARD);
}

int main(void)
{
	T_RUN(test_warmup_suppresses_then_forwards);
	T_RUN(test_level_tracked_through_warmup);
	T_RUN(test_duplicates_dropped);
	T_END();
}

/*
 * hub: the single writer (DESIGN.md Section 2). Accepts sensor daemons on
 * $PSS_RUN_DIR/hub.sock, turns PIR edges into events, asks camd for an image
 * burst per event, and commits everything through the store (mechanism D).
 *
 * M3 scope: no fusion yet (needs collected data, M4). A PIR rise opens a
 * MOTION_ONLY event; a sound onset (below) with no PIR opens a SOUND_ONLY
 * event. Every successful burst is kept.
 *
 * M3 sound trigger (stand-in for DESIGN.md Section 4's detectors, M4): an
 * EWMA background model of spectral flux and log RMS, learned only while no
 * event is open. A frame is an onset when its flux z-score and its loudness
 * above the room background both pass thresholds, so steady noise (fans,
 * AC) never triggers: its flux stays near its own mean and its level is the
 * background. Thresholds are placeholders until tuned on Pi recordings.
 *
 * Exit codes: 0 on SIGTERM/SIGINT, 1 on error (including any store write
 * failure, so the supervisor restarts us and recovery runs), 2 on usage.
 */
#include "common/ipc.h"
#include "common/log.h"
#include "common/time.h"
#include "common/util.h"
#include "store/clip.h"
#include "store/evlog.h"

#include <errno.h>
#include <getopt.h>
#include <inttypes.h>
#include <math.h>
#include <signal.h>
#include <stdio.h>
#include <string.h>
#include <sys/epoll.h>
#include <sys/signalfd.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <unistd.h>

#define EXIT_USAGE 2

