546	{
547		const int sigs[] = { SIGINT, SIGTERM };
548		struct hub *h = &hub;
549		int code = 1;
550	
551		pss_log_init("hub");
552		h->listen_fd = h->epoll_fd = h->sig_fd = h->tick_fd = -1;
553		for (int i = 0; i < MAX_CONNS; i++)
554			h->conns[i].fd = -1;
555		if (parse_args(h, argc, argv) != 0) {
556			usage();
557			return EXIT_USAGE;
558		}
559	
560		h->sig_fd = pss_signalfd(sigs, 2);
561		if (h->sig_fd < 0)
562			goto out;
563		if (mkdir(pss_run_dir(), 0755) != 0 && errno != EEXIST) {
564			pss_log("mkdir %s: %s", pss_run_dir(), strerror(errno));
565			goto out;
566		}
567		if (store_open(&h->store, pss_data_dir()) != 0)
568			goto out;
569		h->store_open = 1;
570		if (write_boot(h) != 0)
571			goto out;
572		if (ipc_sock_path(h->sock_path, sizeof h->sock_path) != 0)
573			goto out;
574		h->listen_fd = ipc_listen(h->sock_path);
575		if (h->listen_fd < 0)
576			goto out;
577		h->tick_fd = pss_timerfd(PSS_NS_PER_S, PSS_NS_PER_S);
578		if (h->tick_fd < 0)
579			goto out;
580		h->epoll_fd = epoll_create1(EPOLL_CLOEXEC);
581		if (h->epoll_fd < 0) {
582			pss_log("epoll_create1: %s", strerror(errno));
583			goto out;
584		}
585		if (epoll_add(h, h->listen_fd, TAG_LISTEN) != 0 || epoll_add(h, h->sig_fd, TAG_SIG) != 0 ||
586		    epoll_add(h, h->tick_fd, TAG_TICK) != 0)
587			goto out;
588	
589		h->start_ns = pss_mono_ns();
590		h->next_hb_ns = h->start_ns + HB_FIRST_NS;
591		pss_log("start pid=%d data=%s sock=%s quiet=%" PRId64 "ms burst=%" PRIu32 "x%" PRIu32 "ms onset z>=%.0f +%.0fdB warmup=%" PRIu32,
592			(int)getpid(), pss_data_dir(), h->sock_path, h->quiet_ns / PSS_NS_PER_MS,
593			h->burst_frames, h->burst_interval_ms, h->onset_z, h->onset_db, h->mic_warmup);
594	
595		for (;;) {
596			struct epoll_event evs[16];
597			int n = epoll_wait(h->epoll_fd, evs, 16, -1);
598			int64_t now;
599	
600			if (n < 0) {
601				if (errno == EINTR)
602					continue;
603				pss_log("epoll_wait: %s", strerror(errno));
604				goto out;
605			}
606			now = pss_mono_ns();
607			for (int i = 0; i < n; i++) {
608				uint32_t tag = evs[i].data.u32;
609	
610				if (tag == TAG_SIG) {
611					struct signalfd_siginfo si;
612	
613					if (read(h->sig_fd, &si, sizeof si) != (ssize_t)sizeof si)
614						pss_log("signalfd read: %s", strerror(errno));
615					else
616						pss_log("signal %u, shutting down", si.ssi_signo);
617					if (h->ev.open) {
618						if (h->ev.burst == BURST_PENDING)
619							h->ev.flags |= PSS_EVF_NO_IMAGES;
620						if (close_event(h, now, PSS_EVF_CLOSED_AT_SHUTDOWN) != 0)
621							goto out;
622					}
623					code = 0;
624					goto out;
625				} else if (tag == TAG_LISTEN) {
626					accept_all(h, now);
627				} else if (tag == TAG_TICK) {
628					if (pss_timerfd_drain(h->tick_fd) != 0 || tick(h, now) != 0)
629						goto out;
630				} else if (tag < MAX_CONNS) {
631					conn_readable(h, (int)tag, now);
632				}
633			}
634		}
635	out:
636		for (int i = 0; i < MAX_CONNS; i++)
637			if (h->conns[i].fd >= 0)
638				close(h->conns[i].fd);
639		if (h->epoll_fd >= 0)
640			close(h->epoll_fd);
641		if (h->listen_fd >= 0) {
642			close(h->listen_fd);
643			if (unlink(h->sock_path) != 0)
644				pss_log("unlink %s: %s", h->sock_path, strerror(errno));
645		}
646		if (h->tick_fd >= 0)
647			close(h->tick_fd);
648		if (h->sig_fd >= 0)
649			close(h->sig_fd);
650		if (h->store_open)
651			store_close(&h->store);
652		pss_log("exit %d", code);
653		return code;
654	}
